import{_ as t,o as a,c as s,ae as n}from"./chunks/framework.CsNvqnj7.js";const u=JSON.parse('{"title":".me Kernel — Role in NRP","description":"","frontmatter":{},"headers":[],"relativePath":"NRP-Kernel-Role.md","filePath":"NRP-Kernel-Role.md"}'),o={name:"NRP-Kernel-Role.md"};function r(l,e,i,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="me-kernel-—-role-in-nrp" tabindex="-1">.me Kernel — Role in NRP <a class="header-anchor" href="#me-kernel-—-role-in-nrp" aria-label="Permalink to &quot;.me Kernel — Role in NRP&quot;">​</a></h1><p>The <code>.me</code> kernel is the <strong>semantic authority</strong> of the stack.</p><p><code>me://</code> addresses, NRP expressions, and Beatle channels are all ways of pointing <em>toward</em> meaning. The meaning itself lives in the kernel.</p><hr><h2 id="the-stack" tabindex="-1">The Stack <a class="header-anchor" href="#the-stack" aria-label="Permalink to &quot;The Stack&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Beatle         — input/control surface (writes NRP expressions)</span></span>
<span class="line"><span>NRP            — resolves me:// expressions to endpoints</span></span>
<span class="line"><span>netget         — HTTP/WebSocket gateway</span></span>
<span class="line"><span>monad          — runtime that owns a kernel instance</span></span>
<span class="line"><span>.me kernel     — where meaning actually lives</span></span></code></pre></div><p>Beatle opens a channel. NRP traces the route. <code>.me</code> decides what is there.</p><hr><h2 id="what-the-kernel-owns" tabindex="-1">What the Kernel Owns <a class="header-anchor" href="#what-the-kernel-owns" aria-label="Permalink to &quot;What the Kernel Owns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thing</th><th>Where it lives</th></tr></thead><tbody><tr><td>Identity</td><td><code>me[ME_RESEED](username, password)</code> → compound seed</td></tr><tr><td>Memory paths</td><td><code>me.profile.name</code>, <code>me.wallet.hidden.*</code></td></tr><tr><td>Secret scopes</td><td><code>me.path[&quot;_&quot;](&quot;key&quot;)</code> — stealth by default</td></tr><tr><td>Audience rules</td><td>Who can read a path</td></tr><tr><td>Capabilities</td><td>What operations are allowed</td></tr><tr><td>Hash-chain</td><td>Integrity across all writes (A8 axiom)</td></tr></tbody></table><hr><h2 id="axioms-that-affect-nrp" tabindex="-1">Axioms That Affect NRP <a class="header-anchor" href="#axioms-that-affect-nrp" aria-label="Permalink to &quot;Axioms That Affect NRP&quot;">​</a></h2><p><strong>A0/A2 — Stealth</strong>: a secret scope root returns <code>undefined</code>, not a &quot;not found&quot; error. The existence of the secret is not revealed. NRP maps this to disclosure level <code>stealth</code>.</p><p><strong>A3 — Nested secrets</strong>: secrets inherit scope chain. A path near a secret scope does not accidentally leak.</p><p><strong>A8 — Hash-chain integrity</strong>: every write is chained. NRP can verify freshness without trusting the transport.</p><p><strong>A9 — LWW conflict resolution</strong>: if two monads write the same path concurrently, the last-write-wins rule is deterministic.</p><hr><h2 id="kernel-vs-address" tabindex="-1">Kernel vs Address <a class="header-anchor" href="#kernel-vs-address" aria-label="Permalink to &quot;Kernel vs Address&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>me://jabellae          ← address form (NRP expression)</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>NRP resolves →         monad running jabellae&#39;s kernel</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>kernel.users.jabellae  ← actual memory location</span></span></code></pre></div><p>The address <code>me://jabellae</code> is not the meaning. It is a pointer that NRP resolves to a kernel path on a specific monad.</p><hr><h2 id="why-nrp-does-not-trust-the-client" tabindex="-1">Why NRP Does Not Trust the Client <a class="header-anchor" href="#why-nrp-does-not-trust-the-client" aria-label="Permalink to &quot;Why NRP Does Not Trust the Client&quot;">​</a></h2><p>The Beatle client sends <code>{ raw, canonical, ast }</code> as hint/intent. The NRP server:</p><ol><li>Re-parses <code>canonical</code> with its own parser.</li><li>Resolves each leaf namespace against a real kernel instance.</li><li>Checks audience rules before returning endpoints.</li><li>Assigns <code>disclosure</code> level based on what the kernel reveals.</li></ol><p>The kernel is the oracle. The client is a user interface.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Algebra-of-Contexts.html">Algebra of Contexts</a></li><li><a href="./../../../neurons-me.github.io/docs/NRP/Namespace-Protocol-Resolution.html">NRP — Namespace Protocol Resolution</a></li><li><a href="./../../../neurons-me.github.io/docs/NRP/Disclosure-Levels.html">Disclosure Levels</a></li></ul>`,28)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
